import sys

def solve():
    input = sys.stdin.readline
    T = int(input())
    ans = []

    for _ in range(T):
        n, x = map(int, input().split())
        s = input().strip()

        pref = [0]
        cur = 0
        for ch in s:
            if ch == '0':
                cur += 1
            else:
                cur -= 1
            pref.append(cur)

        total = pref[n]

        if total == 0:
            # If any prefix balance in one block equals x, then infinitely many.
            if x in pref:
                ans.append("-1")
            else:
                ans.append("0")
        else:
            cnt = 0
            for v in pref:
                diff = x - v
                if diff % total == 0 and diff // total >= 0:
                    cnt += 1
            # Empty prefix is included correctly by pref[0]
            ans.append(str(cnt))

    print("\n".join(ans))

if __name__ == "__main__":
    solve()
